INSERT INTO `about_us_translations` (`id`, `about_us_id`, `title`, `description`, `mission`, `vision`, `value`, `locale`, `created_at`, `updated_at`) VALUES
(1, 1, 'رحلتنا نحو الاستقدام: الإبداع في الخدمة', 'في شركة بلاتنيوم الشرقية للاستقدام، نحن نؤمن بأن البيت هو المكان الذي ينعكس فيه الدفء والرعاية. نقدم خدمات الاستقدام بروح إبداعية، حيث نسعى جاهدين لتحويل البيوت إلى أماكن تنبض بالحياة والسعادة.', NULL, NULL, NULL, 'ar', '2023-12-24 08:07:58', '2023-12-24 08:07:58'),
(2, 1, 'Our Journey Towards Recruitment: Innovation in Service', 'At Achieve Recruitment Company, we believe that home is where warmth and care are reflected. We offer recruitment services with a creative spirit, striving to transform houses into vibrant and happy spaces.', NULL, NULL, NULL, 'en', '2023-12-24 08:07:58', '2023-12-24 08:07:58'),
(3, 2, 'لماذا نحن؟', 'في رحلتنا نحو تقديم أفضل خدمات الاستقدام، نجمع بين الاحترافية والإبداع. نحن هنا لتلبية احتياجات منازلكم بفريق من العمالة المدربة بعناية ومهنية، سعينا لتحقيق الاستقدام بمستوى جديد من الفخامة والابتكار.', NULL, NULL, NULL, 'ar', '2023-12-24 08:18:09', '2023-12-24 08:18:09'),
(4, 2, 'Why us ?', '\"In our journey towards providing the best recruitment services, we combine professionalism with creativity. We are here to meet the needs of your homes with a carefully trained and professional team, aiming to achieve recruitment at a new level of luxury', NULL, NULL, NULL, 'en', '2023-12-24 08:18:09', '2023-12-24 08:18:09'),
(5, 3, 'قيمنا:', '<p style=\"text-align: right; line-height: 1;\"><strong>الاحترافية:</strong></p>\r\n<p style=\"text-align: right; line-height: 1;\">نلتزم بتقديم خدمات استقدام عالية الجودة بمستوى عالٍ من الاحترافية</p>\r\n<p style=\"text-align: right; line-height: 1;\"><strong>الإبداع:</strong></p>\r\n<p style=\"text-align: right; line-height: 1;\">نسعى دومًا لتقديم حلاً مبتكرًا ومميزًا لاحتياجاتكم المنزلية</p>\r\n<p style=\"text-align: right; line-height: 1;\"><strong>الجودة:</strong></p>\r\n<p style=\"text-align: right; line-height: 1;\">نفهم أهمية جودة الخدمة في خلق تجربة مرضية ومستدامة</p>', NULL, NULL, NULL, 'ar', '2023-12-24 08:22:13', '2023-12-26 17:59:02'),
(6, 3, 'Values:', '<p style=\"line-height: 1;\"><strong>Professionalism</strong>:</p>\r\n<p style=\"line-height: 1;\">We are committed to providing high-quality recruitment services with a high level of professionalism.</p>\r\n<p style=\"line-height: 1;\"><strong>Creativity</strong>:</p>\r\n<p style=\"line-height: 1;\">We always strive to offer innovative and distinctive solutions for your household needs.</p>\r\n<p style=\"line-height: 1;\"><strong>Quality</strong>:</p>\r\n<p style=\"line-height: 1;\">We understand the importance of service quality in creating a satisfying and sustainable experience</p>', NULL, NULL, NULL, 'en', '2023-12-24 08:22:13', '2023-12-26 17:59:02');
